1614   const html = document.documentElement;
1615   if (theme === "light") {
1616     html.dataset.theme = "light";
1617   } else if (theme === "dark") {
1618     html.dataset.theme = "dark";
1619   } else {
1620     delete html.dataset.theme;
1621   }
1622   // Both the accent solver and the on-background text depend on the theme
1623   // (surface + the "none" background follow it) — re-run them on switch.
1624   applyDerivedAccent(lastDominant);
1625   if (useThemeOnBackground) clearOnBackground();
1626   else applyOnBackground(lastBgLum);
