1629 export function applyBackground(bg, customDataUrl = null) {
1630   const root = document.documentElement;
1631   root.style.removeProperty("--bg");
1632   if (!bg || bg.type === "none") {
1633     root.style.removeProperty("--bg-image");
1634   } else if (isDefaultBackground(bg)) {
1635     root.style.setProperty("--bg-image", "var(--default-bg-image)");
1636   } else if (bg.type === "solid") {
1637     root.style.removeProperty("--bg-image");
1638     root.style.setProperty("--bg", bg.value);
1639   } else if (bg.type === "gradient") {
1640     root.style.setProperty("--bg-image", bg.value);
1641   } else if (bg.type === "photo") {
1642     root.style.setProperty("--bg-image", `url("${bg.value}")`);
1643   } else if (bg.type === "custom") {
1644     if (customDataUrl) {
1645       root.style.setProperty("--bg-image", `url("${customDataUrl}")`);
1646     } else {
1647       root.style.removeProperty("--bg-image");
1648     }
1649   }
