    24	    const req = indexedDB.open(DB_NAME, DB_VERSION);
    25	    req.onupgradeneeded = () => {
    26	      const db = req.result;
    27	      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);
