 43	function selectKeys(values, keys) {
 44	  if (keys == null) return { ...values };
 45	  if (typeof keys === "string") return { [keys]: values[keys] };
 46	  if (Array.isArray(keys)) {
 47	    return Object.fromEntries(keys.map((key) => [key, values[key]]));
 48	  }
 49	  return Object.fromEntries(
