 57	export function createChromeStorage(initial = {}) {
 58	  const values = {
 59	    sync: { ...(initial.sync ?? {}) },
 60	    local: { ...(initial.local ?? {}) },
 61	  };
 62	  const listeners = [];
 63	
 64	  function emit(area, changes) {
 65	    for (const listener of [...listeners]) listener(changes, area);
 66	  }
 67	
 68	  function makeArea(area) {
 69	    return {
 70	      async get(keys) {
 71	        return selectKeys(values[area], keys);
 72	      },
 73	      async set(next) {
 74	        const changes = {};
 75	        for (const [key, newValue] of Object.entries(next)) {
 76	          changes[key] = { oldValue: values[area][key], newValue };
 77	          values[area][key] = newValue;
 78	        }
 79	        emit(area, changes);
 80	      },
 81	    };
 82	  }
 83	
 84	  return {
 85	    chrome: {
 86	      storage: {
 87	        sync: makeArea("sync"),
 88	        local: makeArea("local"),
 89	        onChanged: {
 90	          addListener(listener) {
 91	            listeners.push(listener);
 92	          },
 93	        },
 94	      },
 95	    },
 96	    emit,
 97	    values,
 98	  };
 99	}
